  "source_tiers": [
    {
      "tier": 1,
      "name": "official_structured_feed",
      "trust_level": "Highest for timestamps, timezones, persistent IDs, addresses, and structured access flags.",
      "assignment_rule": "Assign when the fact comes from a non-truncated typed field in an official central university json_feed (events.nyu.edu LiveWhale or events.columbia.edu Bedework), such as nyu-05, nyu-15, col-01, col-03, and col-05."
    },
    {
      "tier": 2,
      "name": "primary_host_html",
      "trust_level": "High for program descriptions, room details, featured people, and host-specific RSVP instructions; prefer over Tier 3 reposts.",
      "assignment_rule": "Assign when the fact comes from event metadata blocks or event-specific prose on a static_html page served from an official campus domain (*.nyu.edu, *.columbia.edu, nyu.libcal.com) whose site owner is the primary event host (nyu-01, nyu-02, nyu-04, nyu-07, nyu-10, nyu-12, nyu-14, nyu-17)."
    },
    {
      "tier": 3,
      "name": "secondary_campus_repost_or_linked_platform",
      "trust_level": "Moderate; trusted when Tiers 1-2 are absent, but yields to Tiers 1-2 on schedule or venue conflicts, and detailed body schedules override summary widgets on the same page.",
      "assignment_rule": "Assign when a campus page cross-lists an event run by a different unit or venue (nyu-09 on LibCal pointing to CRACS Co-Lab; col-07 on cc-seas listing The Forum's market), when a date component such as year is inferred from the URL slug plus weekday agreement (nyu-02, nyu-17), or when RSVP details come from a campus-linked external ticketing page (Eventbrite in col-01, Luma in nyu-04)."
    },
